<template><div><div class="d-flex justify-content-between align-items-center mb-4"><div><h4 class="mb-1">Publicidade</h4><p class="text-muted mb-0">Campanhas pagas e parceiros exibidos na Home pública.</p></div><button class="btn btn-primary" @click="newAd"><i class="ri-add-line me-1"></i> Nova campanha</button></div><div class="card"><div class="card-body"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Anunciante</th><th>Posição</th><th>Período</th><th>Status</th><th>Impressões</th><th>Cliques / CTR</th><th>Valor</th><th></th></tr></thead><tbody><tr v-for="x in items" :key="x.id"><td><b>{{x.advertiserName}}</b><small class="d-block text-muted">{{x.title}}</small></td><td>{{positionLabel(x.position)}}</td><td>{{date(x.startDate)}} → {{date(x.endDate)}}</td><td><span class="badge" :class="x.status==='ACTIVE'?'bg-success':'bg-secondary'">{{x.status}}</span></td><td>{{num(x.impressions)}}</td><td>{{num(x.clicks)}} <small class="text-muted">({{ctr(x)}}%)</small></td><td>{{money(x.contractValue)}}</td><td class="text-end"><button class="btn btn-sm btn-soft-info me-1" @click="edit(x)"><i class="ri-pencil-line"></i></button><button class="btn btn-sm btn-soft-danger" @click="remove(x)"><i class="ri-delete-bin-line"></i></button></td></tr><tr v-if="!items.length"><td colspan="8" class="text-center text-muted py-5">Nenhuma campanha cadastrada.</td></tr></tbody></table></div></div></div>
<div v-if="modalOpen" class="modal d-block ad-modal" tabindex="-1"><div class="modal-dialog modal-xl modal-dialog-scrollable"><div class="modal-content"><div class="modal-header"><h5 class="modal-title">{{form.id?'Editar':'Nova'}} campanha</h5><button class="btn-close" @click="modalOpen=false"></button></div><div class="modal-body"><div class="row g-3"><div class="col-md-6"><label>Anunciante</label><input v-model="form.advertiserName" class="form-control"></div><div class="col-md-6"><label>Título da campanha</label><input v-model="form.title" class="form-control"></div><div class="col-12"><label>Descrição</label><textarea v-model="form.description" class="form-control" rows="2"></textarea></div><div class="col-md-3"><label>Posição</label><select v-model="form.position" class="form-select"><option value="HOME_PREMIUM">Banner da Home</option><option value="HOME_PARTNERS">Parceiros Seven Shows</option></select></div><div class="col-md-3"><label>Status</label><select v-model="form.status" class="form-select"><option value="ACTIVE">Ativo</option><option value="PAUSED">Pausado</option><option value="SCHEDULED">Agendado</option><option value="ENDED">Encerrado</option></select></div><div class="col-md-3"><label>Início</label><input v-model="form.startDate" type="datetime-local" class="form-control"></div><div class="col-md-3"><label>Fim</label><input v-model="form.endDate" type="datetime-local" class="form-control"></div><div class="col-md-4"><label>Valor contratado</label><input v-model.number="form.contractValue" type="number" step="0.01" class="form-control"></div><div class="col-md-8"><label>Destino do anúncio</label><div class="form-control bg-light text-muted" style="height:auto">O destino é escolhido automaticamente pelos campos preenchidos, nesta prioridade: Site → WhatsApp → Instagram → Facebook. Apenas um botão será exibido e sempre abrirá em uma nova aba.</div></div><div class="col-md-4"><label>WhatsApp</label><input v-model="form.whatsApp" class="form-control" placeholder="5543999999999"></div><div class="col-md-8"><label>Mensagem inicial WhatsApp</label><input v-model="form.whatsAppMessage" class="form-control"></div><div class="col-md-6"><label>Instagram URL</label><input v-model="form.instagramUrl" class="form-control"></div><div class="col-md-6"><label>Site URL</label><input v-model="form.websiteUrl" class="form-control"></div><div class="col-md-6"><label>Facebook URL</label><input v-model="form.destinationUrl" class="form-control" placeholder="https://facebook.com/sua-pagina"></div><div class="col-md-6"><label>Cidade</label><input v-model="form.city" class="form-control"></div><div class="col-md-2"><label>UF</label><input v-model="form.state" maxlength="2" class="form-control"></div><div class="col-12"><hr><h6 class="mb-1">Identidade visual da campanha</h6><p class="text-muted small mb-2">A publicidade é exibida somente como imagem, sem logo ou textos adicionados pela Seven Shows. Use banner full para Banner da Home ou banner horizontal para o card de Parceiros Seven Shows.</p></div><div class="col-md-6"><label>{{form.position==='HOME_PREMIUM'?'Banner full desktop — recomendado 1600 × 500 px (16:5) *':'Banner do card — recomendado 800 × 450 px (16:9) *'}}</label><div class="upload-box"><img v-if="form.desktopImageUrl" :src="imageUrl(form.desktopImageUrl)" class="upload-preview banner-preview"><div v-else class="upload-empty"><i class="ri-image-add-line"></i><span>Nenhuma arte enviada</span></div><input ref="desktopFile" type="file" accept="image/jpeg,image/png,image/webp" class="d-none" @change="onFile($event,'desktopImageUrl')"><button type="button" class="btn btn-outline-primary btn-sm" @click="$refs.desktopFile.click()"><i class="ri-upload-2-line me-1"></i>{{form.desktopImageUrl?'Substituir arte':'Enviar arte'}}</button><button v-if="form.desktopImageUrl" type="button" class="btn btn-link btn-sm text-danger" @click="form.desktopImageUrl=''">Remover</button></div></div><div v-if="form.position==='HOME_PREMIUM'" class="col-md-6"><label>Banner full mobile — recomendado 1080 × 1350 px (4:5)</label><div class="upload-box"><img v-if="form.mobileImageUrl" :src="imageUrl(form.mobileImageUrl)" class="upload-preview mobile-preview"><div v-else class="upload-empty"><i class="ri-smartphone-line"></i><span>Opcional</span></div><input ref="mobileFile" type="file" accept="image/jpeg,image/png,image/webp" class="d-none" @change="onFile($event,'mobileImageUrl')"><button type="button" class="btn btn-outline-primary btn-sm" @click="$refs.mobileFile.click()"><i class="ri-upload-2-line me-1"></i>{{form.mobileImageUrl?'Substituir arte':'Enviar arte'}}</button><button v-if="form.mobileImageUrl" type="button" class="btn btn-link btn-sm text-danger" @click="form.mobileImageUrl=''">Remover</button></div></div></div></div><div class="modal-footer"><button class="btn btn-light" @click="modalOpen=false">Cancelar</button><button class="btn btn-primary" :disabled="saving" @click="save">{{saving?'Salvando...':'Salvar campanha'}}</button></div></div></div></div><div v-if="modalOpen" class="modal-backdrop fade show"></div></div></template>
<script>
import axios from'axios';
const base=process.env.VUE_APP_API_BASE_URL;const auth=()=>({headers:{Authorization:`Bearer ${localStorage.getItem('jwt')}`}});
export default{name:'AdminPublicidade',data(){return{items:[],modalOpen:false,saving:false,form:{}}},mounted(){this.load()},methods:{blank(){let d=new Date(),e=new Date(Date.now()+30*864e5);let local=x=>new Date(x.getTime()-x.getTimezoneOffset()*60000).toISOString().slice(0,16);return{advertiserName:'',title:'',description:'',position:'HOME_PREMIUM',destinationType:'NONE',status:'ACTIVE',startDate:local(d),endDate:local(e),contractValue:0,whatsAppMessage:'Olá! Vi sua publicidade no Seven Shows e gostaria de mais informações.'}},async load(){this.items=(await axios.get(`${base}/advertising/admin`,auth())).data||[]},newAd(){this.form=this.blank();this.modalOpen=true},edit(x){this.form={...x,startDate:this.toLocal(x.startDate),endDate:this.toLocal(x.endDate)};this.modalOpen=true},toLocal(x){if(!x)return'';let d=new Date(x);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)},async onFile(event,field){let file=event.target.files&&event.target.files[0];if(!file)return;if(file.size>8*1024*1024){alert('A imagem deve ter no máximo 8 MB.');event.target.value='';return}try{let fd=new FormData();fd.append('file',file);let r=await axios.post(`${base}/advertising/admin/upload`,fd,{headers:{Authorization:`Bearer ${localStorage.getItem('jwt')}`}});let payload=r&&r.data!==undefined?r.data:r;let url=payload&&payload.url;if(!url)throw new Error('A API concluiu o upload, mas não retornou a URL da imagem.');this.form[field]=url}catch(e){alert((e.response&&e.response.data&&e.response.data.message)||'Não foi possível enviar a imagem.')}finally{event.target.value=''}},imageUrl(u){if(!u)return'';if(/^https?:/.test(u))return u;let b=(base||'').replace(/\/api\/?$/,'');return `${b}${u.startsWith('/')?'':'/'}${u}`},async save(){if(!this.form.advertiserName||!this.form.title)return alert('Informe anunciante e título.');if(this.form.position==='HOME_PARTNERS'&&!this.form.desktopImageUrl)return alert('Para Parceiros Seven Shows, envie o banner do card.');if(this.form.position==='HOME_PREMIUM'&&!this.form.desktopImageUrl&&!this.form.mobileImageUrl)return alert('Para Banner da Home, envie a arte/banner da campanha.');this.saving=true;try{let data={...this.form,startDate:new Date(this.form.startDate).toISOString(),endDate:new Date(this.form.endDate).toISOString()};if(this.form.id)await axios.put(`${base}/advertising/admin/${this.form.id}`,data,auth());else await axios.post(`${base}/advertising/admin`,data,auth());this.modalOpen=false;await this.load()}finally{this.saving=false}},async remove(x){if(!confirm(`Excluir a campanha de ${x.advertiserName}?`))return;await axios.delete(`${base}/advertising/admin/${x.id}`,auth());await this.load()},positionLabel(x){return x==='HOME_PREMIUM'?'Banner da Home':'Parceiros Seven Shows'},date(x){return x?new Date(x).toLocaleDateString('pt-BR'):'-'},num(x){return Number(x||0).toLocaleString('pt-BR')},money(x){return Number(x||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})},ctr(x){return x.impressions?((x.clicks/x.impressions)*100).toFixed(2):'0,00'}}}
</script>
<style scoped>.ad-modal{background:rgba(0,0,0,.25);z-index:1055}.ad-modal+.modal-backdrop{z-index:1050}label{font-size:12px;font-weight:700;margin-bottom:5px}.table td{vertical-align:middle}.upload-box{min-height:205px;border:1px dashed #cfd5dc;border-radius:10px;padding:12px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:9px;background:#fafbfc}.upload-empty{height:105px;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#8b95a5;gap:5px}.upload-empty i{font-size:30px}.upload-preview{display:block;max-width:100%;object-fit:contain}.banner-preview{width:100%;height:105px;border-radius:7px;background:#111}.mobile-preview{height:105px;max-width:75px;border-radius:7px;background:#111}</style>
